using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class BFFApply {
 const string A="Assets/Afrer_Seconds/05.Model/",E=A+"Environment/B4/",P=A+"Props/B4/";static string Repo=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static Transform root,full;static JObject plan;static Dictionary<string,Material> mats=new Dictionary<string,Material>();static List<string> hidden=new List<string>();static int fixtureCount;static Mesh labelMesh;
 static Vector3 V(JToken t)=>new Vector3((float)t[0],(float)t[1],(float)t[2]);
 static GameObject Child(string n,Transform p){var g=new GameObject(n);g.transform.SetParent(p,false);return g;}
 static Material Map(Material m,int screen=0){if(!m)return mats["B4O_Coat"];if(mats.TryGetValue(m.name,out var exact)&&(m.name.StartsWith("BF_Display_")||!(screen>0&&m.name.Contains("Display"))))return exact;if(m.name.Contains("Display")||m.name.Contains("Screen")||m.name.Contains("LCD"))return mats["BF_Display_"+(screen>0?screen:7).ToString("00")];foreach(string k in new[]{"Glass","Lamp","Indicator","Lens","Rubber","Dark","Fabric","Floor","Steel","Paper","Hazard","Red","Mark","Coat"})if(m.name.Contains(k))return mats["B4O_"+k];return mats["B4O_Coat"];}
 static GameObject Place(string n,string path,Transform parent,Vector3 pos,float yaw=0,bool mesh=false,Vector3 size=default(Vector3),Vector3 center=default(Vector3),int screen=0){var src=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(!src)throw new Exception("Missing asset "+path);var g=(GameObject)PrefabUtility.InstantiatePrefab(src,parent);g.name=n;g.transform.localPosition=pos;g.transform.localRotation=Quaternion.Euler(0,yaw,0);foreach(var c in g.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(c);foreach(var l in g.GetComponentsInChildren<Light>(true))UnityEngine.Object.DestroyImmediate(l);foreach(var r in g.GetComponentsInChildren<Renderer>())r.sharedMaterials=r.sharedMaterials.Select(m=>Map(m,screen)).ToArray();
  if(mesh)foreach(var mf in g.GetComponentsInChildren<MeshFilter>())mf.gameObject.AddComponent<MeshCollider>().sharedMesh=mf.sharedMesh;
  if(size!=Vector3.zero){var c=g.AddComponent<BoxCollider>();c.center=center;c.size=size;}
  return g;
 }
 static void Fixtures(string name,Transform parent,Vector3 pos,Quaternion rotation,float power,float range,float angle=115){var go=Place(name,E+"BO_SealedTaskLight.fbx",parent,pos);go.transform.localRotation=rotation;var g=Child("광원",go.transform);g.transform.localPosition=new Vector3(0,-.06f,0);g.transform.localRotation=Quaternion.Euler(90,0,0);var l=g.AddComponent<Light>();l.type=LightType.Spot;l.spotAngle=angle;l.innerSpotAngle=angle*.68f;l.color=new Color(.92f,.95f,1);l.intensity=power;l.range=range;l.shadows=LightShadows.Soft;l.shadowBias=.01f;l.shadowNormalBias=.015f;l.shadowNearPlane=.1f;var u=l.GetUniversalAdditionalLightData();u.usePipelineSettings=false;var so=new SerializedObject(u);so.FindProperty("m_AdditionalLightsShadowResolutionTier").intValue=0;so.ApplyModifiedPropertiesWithoutUndo();fixtureCount++;}
 static void Materials(){AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);foreach(string path in Directory.GetFiles(Path.Combine(Application.dataPath,"..",E+"Materials"),"B4O_*.mat")){var m=AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/"+Path.GetFileName(path));mats[m.name]=m;}
  foreach(var file in Directory.GetFiles(Path.Combine(Application.dataPath,"..",P+"Textures"),"BF_*.png")){string path=P+"Textures/"+Path.GetFileName(file);var ti=(TextureImporter)AssetImporter.GetAtPath(path);ti.mipmapEnabled=true;ti.maxTextureSize=2048;ti.filterMode=FilterMode.Trilinear;ti.wrapMode=TextureWrapMode.Clamp;ti.alphaIsTransparency=path.Contains("Guide");ti.textureCompression=TextureImporterCompression.CompressedHQ;ti.SaveAndReimport();string n=Path.GetFileNameWithoutExtension(path);var m=new Material(Shader.Find("Universal Render Pipeline/Lit")){name=n};m.SetColor("_BaseColor",Color.white);m.SetFloat("_Smoothness",.25f);m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(path));if(n.Contains("Display")){m.SetTexture("_EmissionMap",AssetDatabase.LoadAssetAtPath<Texture2D>(path));m.SetColor("_EmissionColor",Color.white*.65f);m.EnableKeyword("_EMISSION");m.globalIlluminationFlags=MaterialGlobalIlluminationFlags.BakedEmissive;m.SetFloat("_SpecularHighlights",0);}else{m.SetFloat("_AlphaClip",1);m.SetFloat("_Cutoff",.4f);m.EnableKeyword("_ALPHATEST_ON");m.SetOverrideTag("RenderType","TransparentCutout");m.renderQueue=2450;}AssetDatabase.CreateAsset(m,E+"Materials/"+n+".mat");mats[n]=m;}
  var colors=JObject.Parse(File.ReadAllText(Repo+"/SourceAssets/B4_FullFloor/guide_colors.json"));foreach(var kv in colors){ColorUtility.TryParseHtmlString("#"+(string)kv.Value,out var c);var m=new Material(Shader.Find("Universal Render Pipeline/Lit")){name="BF_Line_"+kv.Key};m.SetColor("_BaseColor",c);m.SetFloat("_Smoothness",.2f);AssetDatabase.CreateAsset(m,E+"Materials/"+m.name+".mat");mats[m.name]=m;}
  foreach(string folder in new[]{E,P})foreach(var file in Directory.GetFiles(Path.Combine(Application.dataPath,"..",folder),"BF_*.fbx")){string path=folder+Path.GetFileName(file);var m=(ModelImporter)AssetImporter.GetAtPath(path);m.importAnimation=false;m.importCameras=false;m.importLights=false;m.isReadable=true;m.importNormals=ModelImporterNormals.Import;m.importTangents=ModelImporterTangents.CalculateMikk;m.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;foreach(var kv in mats.Where(kv=>kv.Key.StartsWith("B4O_")||kv.Key.StartsWith("BF_Display_")))m.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),kv.Key),kv.Value);m.SaveAndReimport();}
 }
 static void Hide(Transform t){if(!t)throw new Exception("Expected closure missing");t.gameObject.SetActive(false);hidden.Add(t.name);PrefabUtility.RecordPrefabInstancePropertyModifications(t.gameObject);}
 static float ExitDistance(Vector3 p,Vector3 dir,Vector3 center,float radius){var v=p-center;float d=Vector3.Dot(v,dir);return -d+Mathf.Sqrt(Mathf.Max(0,d*d+radius*radius-v.sqrMagnitude));}
 static Mesh Plane(string name,float w,float d){var m=new Mesh{name=name};m.vertices=new[]{new Vector3(-w/2,0,-d/2),new Vector3(w/2,0,-d/2),new Vector3(-w/2,0,d/2),new Vector3(w/2,0,d/2)};m.triangles=new[]{0,2,1,1,2,3};m.uv=new[]{Vector2.zero,Vector2.right,Vector2.up,Vector2.one};m.RecalculateNormals();AssetDatabase.CreateAsset(m,E+name+".asset");return m;}
 static void Visual(string n,Transform parent,Mesh mesh,Material mat,Vector3 pos,float yaw){var g=Child(n,parent);g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=mat;g.transform.localPosition=pos;g.transform.localRotation=Quaternion.Euler(0,yaw,0);}
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B4_Circular.unity"))throw new Exception("Saved B4 edit required");root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B4_")).transform;if(root.Find("B4_전체확장"))throw new Exception("Already applied; target repairs only");plan=JObject.Parse(File.ReadAllText(Repo+"/SourceAssets/B4_FullFloor/layout.json"));Materials();full=Child("B4_전체확장",root).transform;root.name="B4_능력측정관찰층_V0.02";
  foreach(string id in new[]{"B4-T03","B4-T06","B4-T08"})Hide(root.Find("B4_C01_출입구/B4_C01_닫힌문_"+id));Hide(root.Find("B4_T02_접근복도/B4_T02_C02측_닫힌문"));foreach(var n in new[]{"B4_T02_C01_복도안내선","B4_T02_C01_바닥표기"})Hide(root.Find("B4_T02_접근복도/"+n));
  var rooms=plan["rooms"].ToDictionary(r=>(string)r["id"]);var screenMap=new Dictionary<string,int>{{"C02",11},{"C03",7},{"C04",8},{"C05",20},{"W01",9},{"W02",16},{"W03",10},{"E01",15},{"E02",12},{"E03",21},{"N01",18},{"S01",19}};
  foreach(var r in plan["rooms"]){string id=(string)r["id"];if(id=="C01")continue;float radius=(float)r["r"];bool core=(string)r["kind"]=="core";var room=Child("B4_"+id+"_"+(string)r["name"],full).transform;room.localPosition=new Vector3((float)r["x"],0,-(float)r["v"]);var arch=Child("건축",room).transform;var props=Child("운용설비",room).transform;var lighting=Child("조명",room).transform;
   foreach(string part in new[]{"Shell","Floor","Lining","Services"})Place("B4_"+id+"_"+new Dictionary<string,string>{{"Shell","벽체"},{"Floor","바닥"},{"Lining","패널_기둥"},{"Services","환기_배관"}}[part],E+"BF_"+id+"_"+part+".fbx",arch,Vector3.zero,mesh:part=="Shell"||part=="Floor");
   foreach(var p in plan["placements"].Where(p=>(string)p["room"]==id)){bool mesh=(bool)p["meshCollider"];Place((string)p["name"],(string)p["asset"],props,V(p["position"]),(float)p["yaw"],mesh,mesh?Vector3.zero:V(p["size"]),V(p["center"]),screenMap[id]);}
   foreach(var d in r["doors"]){if(id=="C02"&&(string)d["id"]=="B4-T02")continue;var dir=new Vector3((float)d["x"],0,(float)d["z"]).normalized;Place("B4_"+id+"_아치문틀_"+(string)d["id"],E+"BO_VaultPortal.fbx",arch,dir*(radius-.38f),Quaternion.LookRotation(dir).eulerAngles.y);}
   if(!core){int count=radius>=8?8:4;for(int i=0;i<count;i++){float a=(22.5f+360f*i/count)*Mathf.Deg2Rad;var normal=new Vector3(Mathf.Cos(a)*.55f,Mathf.Sqrt(1-.55f*.55f),Mathf.Sin(a)*.55f);var tangent=new Vector3(-Mathf.Sin(a),0,Mathf.Cos(a));Fixtures("B4_"+id+"_천장등_"+(i+1).ToString("00"),lighting,normal*(radius-.23f),Quaternion.LookRotation(Vector3.Cross(tangent,normal),normal),3.5f+radius*.68f,radius*1.6f,120);}
   }else{
    for(int i=0;i<4;i++){float a=(45+i*90)*Mathf.Deg2Rad;var dir=new Vector3(Mathf.Cos(a),0,Mathf.Sin(a));Fixtures("B4_"+id+"_벽작업등_"+(i+1),lighting,dir*4.80f+Vector3.up*3.65f,Quaternion.FromToRotation(Vector3.up,(dir*.8f+Vector3.up*.6f).normalized),4.5f,9f);}
    if(id=="VA"||id=="VB"){
     Place("B4_"+id+"_B3행_17m계단",E+"BF_VerticalStairs.fbx",arch,Vector3.zero,mesh:true);
     for(int i=0;i<8;i++){float y=2.125f*i+2.9f;Fixtures("B4_"+id+"_계단참조명_"+(i+1).ToString("00"),lighting,new Vector3(i%2==0?-4.8f:4.8f,y,0),Quaternion.FromToRotation(Vector3.up,new Vector3(i%2==0?-1:1,.45f,0).normalized),4,8);}
     var door=Place("B4_"+id+"_B3측_닫힌연결문",E+"BO_ClosedVaultDoor.fbx",arch,new Vector3(0,17,-4.5f));door.transform.localScale=new Vector3(.5f,.8f,1);
    }else{Place("B4_VL_화물승강기_캐빈과레일",E+"BF_CargoLift.fbx",arch,Vector3.zero,mesh:true);Fixtures("B4_VL_캐빈조명",lighting,new Vector3(0,3.67f,-1.25f),Quaternion.identity,3,5,110);Place("B4_VL_대기화물",A+"Props/B5/SF_SealedSupplyCrates.fbx",props,new Vector3(-3.15f,0,-.5f),90,size:new Vector3(1.4f,1.1f,.9f),center:new Vector3(0,.55f,0));}
   }
  }
  var corridors=Child("B4_연결복도",full).transform;var guidance=Child("B4_복도전용안내",full).transform;labelMesh=Plane("BF_DestinationLabel",2.9f,.60f);
  foreach(var t in plan["tunnels"]){string id=(string)t["id"],code=id.Split('-')[1];var a=new Vector3((float)t["p"][0],0,-(float)t["p"][1]);var b=new Vector3((float)t["q"][0],0,-(float)t["q"][1]);var forward=(b-a).normalized;float length=(b-a).magnitude,yaw=Quaternion.LookRotation(forward).eulerAngles.y;
   if(code!="T02"){var corridor=Child("B4_"+code+"_"+(string)t["a"]+"↔"+(string)t["b"],corridors).transform;Place("B4_"+code+"_터널벽_바닥",E+"BF_"+code+"_Shell.fbx",corridor,Vector3.zero,mesh:true);Place("B4_"+code+"_배선_배수_보호레일",E+"BF_"+code+"_Finish.fbx",corridor,a,yaw);int bays=Mathf.CeilToInt((length-1.2f)/3f);float span=(length-1.2f)/bays;
    for(int i=0;i<=bays;i++){float dist=.6f+span*i;Place("B4_"+code+"_아치기둥_"+(i+1).ToString("000"),A+"Environment/Common/CFD_TunnelRib.prefab",corridor,a+forward*dist,yaw);if(i<bays&&(i%2==0||i==bays-1))Fixtures("B4_"+code+"_기둥사이등_"+(i+1).ToString("000"),corridor,a+forward*(dist+span*.5f)+Vector3.up*3.31f,Quaternion.Euler(0,yaw,0),5.0f,8f,120);}
   }
   var ra=rooms[(string)t["a"]];var rb=rooms[(string)t["b"]];var ca=new Vector3((float)ra["x"],0,-(float)ra["v"]);var cb=new Vector3((float)rb["x"],0,-(float)rb["v"]);float start=ExitDistance(a,forward,ca,(float)ra["r"]+.22f),end=ExitDistance(b,-forward,cb,(float)rb["r"]+.22f);float usable=length-start-end;var right=Vector3.Cross(Vector3.up,forward);var guide=Child("B4_"+code+"_목적지안내",guidance).transform;
   foreach(int side in new[]{-1,1}){string dest=(string)t[side<0?"a":"b"];var mesh=Plane("BF_"+code+"_To_"+dest,.055f,usable);Visual("B4_"+code+"_"+dest+"행_안내선",guide,mesh,mats["BF_Line_"+dest],a+forward*(start+usable*.5f)+right*(side*.12f)+Vector3.up*.009f,yaw);var lp=a+forward*(start+(side<0?1.65f:usable-1.65f))+right*(side*.85f)+Vector3.up*.015f;Visual("B4_"+code+"_"+dest+"행_바닥표기",guide,labelMesh,mats["BF_Guide_"+dest],lp,yaw+(side<0?90:-90));}
  }
  foreach(var tr in root.GetComponentsInChildren<Transform>(true))if(PrefabUtility.IsPartOfPrefabInstance(tr)){PrefabUtility.RecordPrefabInstancePropertyModifications(tr);PrefabUtility.RecordPrefabInstancePropertyModifications(tr.gameObject);foreach(var rr in tr.GetComponents<Renderer>())PrefabUtility.RecordPrefabInstancePropertyModifications(rr);}
  Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);var result=new{scene=s.path,rooms=16,corridors=22,placedProps=plan["placements"].Count(),addedFixtures=fixtureCount,lights=root.GetComponentsInChildren<Light>().Length,renderers=root.GetComponentsInChildren<Renderer>().Length,colliders=root.GetComponentsInChildren<Collider>().Length,hidden};File.WriteAllText(Repo+"/Docs/검수/2026-11-08_B4_FullFloor/apply.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;
 }
